{"source": "def investigate(context, acquire):
    hist = acquire("history")
    # Family: put mode in {ignore, replace, upsert}, channel in {changes, total_main, total_both}
    # trigger absent or one AFTER INSERT logging one row.
    # We simulate all 18 members and keep those consistent with history.

    def simulate(actions, mode, chan, trig):
        # returns (channel_value, committed_count, committed_sum)
        # state: dict key->value committed; per-connection open txn buffers
        committed = {}
        # transaction state per connection: None or dict of pending ops
        txn = {"main": None, "other": None}
        # total_changes per connection
        tc = {"main": 0, "other": 0}
        # last changes() on main
        last_changes = 0
        # trigger log count (unread but affects total_changes)
        # We'll track total_changes including trigger inserts.

        def apply_put(conn, key, value):
            # returns number of direct row changes (0 or 1) and trigger changes (0 or 1)
            direct = 0
            if mode == "ignore":
                if key not in committed:
                    committed[key] = value
                    direct = 1
            elif mode == "replace":
                committed[key] = value
                direct = 1
            else:  # upsert
                if key in committed:
                    committed[key] = value
                    direct = 1
                else:
                    committed[key] = value
                    direct = 1
            trigc = 0
            if trig and direct == 1:
                trigc = 1
            return direct, trigc

        def apply_update(conn, key, value):
            direct = 0
            if key in committed:
                committed[key] = value
                direct = 1
            trigc = 0
            if trig and direct == 1:
                trigc = 1
            return direct, trigc

        def apply_delete(conn, key):
            direct = 0
            if key in committed:
                del committed[key]
                direct = 1
            trigc = 0
            if trig and direct == 1:
                trigc = 1
            return direct, trigc

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                txn[conn] = {}
            elif op == "commit":
                if txn[conn] is not None:
                    for k, v in txn[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                value = act.get("value")
                # determine target state: if txn open on conn, apply to buffer
                if txn[conn] is not None:
                    # apply to buffer
                    if op == "put":
                        # conflict handling against buffer+committed
                        # For simplicity, treat buffer as overlay
                        if mode == "ignore":
                            if key not in committed and key not in txn[conn]:
                                txn[conn][key] = value
                                direct = 1
                            else:
                                direct = 0
                        elif mode == "replace":
                            txn[conn][key] = value
                            direct = 1
                        else:
                            txn[conn][key] = value
                            direct = 1
                    elif op == "update":
                        if key in committed or key in txn[conn]:
                            txn[conn][key] = value
                            direct = 1
                        else:
                            direct = 0
                    else:  # delete
                        if key in committed or key in txn[conn]:
                            txn[conn][key] = None
                            direct = 1
                        else:
                            direct = 0
                    trigc = 1 if (trig and direct == 1) else 0
                    tc[conn] += direct + trigc
                    if conn == "main":
                        last_changes = direct
                else:
                    # direct apply to committed
                    if op == "put":
                        direct, trigc = apply_put(conn, key, value)
                    elif op == "update":
                        direct, trigc = apply_update(conn, key, value)
                    else:
                        direct, trigc = apply_delete(conn, key)
                    tc[conn] += direct + trigc
                    if conn == "main":
                        last_changes = direct

        if chan == "changes":
            ch = last_changes
        elif chan == "total_main":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    modes = ["ignore", "replace", "upsert"]
    chans = ["changes", "total_main", "total_both"]
    trigs = [False, True]

    candidates = []
    for mode in modes:
        for chan in chans:
            for trig in trigs:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    ch, cc, cs = simulate(acts, mode, chan, trig)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((mode, chan, trig))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for mode, chan, trig in candidates:
        ch, cc, cs = simulate(actions, mode, chan, trig)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
"
, "scope": "Simulates all 18 family members (put mode x channel x trigger) and filters by calibration receipts; predicts only when all consistent members agree.", "lesson": "The channel is not net committed effects; changes() counts last direct row changes, total_changes includes trigger inserts, and INSERT OR IGNORE/REPLACE/upsert differ on conflicts."}
